sys_script.script:
(function executeRule(current, previous /*null when async*/) {
var engine = new CategorizationEngine();
var text = (current.description || '') + ' ' + (current.short_description || '');
var tier = current.u_customer_tier + '';
var result = engine.categorize(text, tier);
current.u_urgency = result.urgency;
current.u_topic = result.topic;
// Product detection
if (text.toLowerCase().includes('mobile') || text.toLowerCase().includes('phone')) {
current.u_product = 'Mobile';
} else if (text.toLowerCase().includes('tv') ||
text.toLowerCase().includes('television')) {
current.u_product = 'TV';
} else if (text.toLowerCase().includes('laptop') ||
text.toLowerCase().includes('computer')) {
current.u_product = 'Laptop';
}
gs.log('Case categorized: urgency=' + result.urgency + ' topic=' + result.topic);
var log = new GlideRecord('u_audit_logs');
log.initialize();
log.u_case = current.sys_id;
log.u_action = 'Categorized: urgency=' + result.urgency + ' topic=' + result.topic;
log.u_time = new GlideDateTime();
log.insert();
})(current, previous);
